,{"name":"Nerve Block","categoryName":"Interventional Procedures","durationMinutes":40,"consentFormRequired":true},{"name":"Trigger Point Injection","categoryName":"Interventional Procedures","durationMinutes":25,"cptCodes":["20552"],"consentFormRequired":true},{"name":"Radiofrequency Denervation","categoryName":"Interventional Procedures","durationMinutes":60,"consentFormRequired":true}],"inventoryCategories":[{"code":"anae_airway","name":"Airway Equipment"},{"code":"anae_drugs","name":"Anaesthetic Drugs"},{"code":"anae_regional","name":"Regional Block Supplies"},{"code":"anae_monitoring","name":"Monitoring Consumables"}],"codeSets":{"icd10":["M54.5","M54.16","G89.29","M79.7","G58.9","Z01.818"],"cpt":["20552"]},"settings":{"defaultAppointmentDuration":30,"slotIntervalMinutes":15},"reports":{"show":["clinical","operational"]}}'::jsonb, true)
